class Inventory(var items: [String]) {
    var count = 0

    // fn note(item: &str, count: &mut i32) { *count += 1; ... }
    fun note(item: String) {
        count += 1
        println("$count: $item")
    }

    // Self::note(&item, &mut self.count)
    fun scan() {
        for (item in items) { note(item) }
    }
}

fun main() {
    var inv = Inventory(["apple", "pear"])
    inv.scan()
}

